-- =====================================================================
-- 0377 — Custom Forms: Position Reassignment & Appointment Agreement
-- (Yujung (Chris) Yong, COO → Director of Business Operations, effective
-- October 14, 2026), text as provided 2026-10-14.
--
-- Three signatures (HR Paperworks → Custom Forms):
--   * Employee — Chris signs and dates his part on the form's link.
--   * Company / Employer (Justin Lee, CEO) and Human Resources — "Filled in
--     by: Company" sections, each signed separately from Submissions →
--     Complete (the submission stays "Awaiting company signature" until both
--     are in; then the finished document is saved).
--
-- Adds one row only — nothing existing is changed. Skips if a form with this
-- title already exists, so it's safe to run twice.
-- Run once in the Supabase SQL Editor.
-- =====================================================================

insert into hr_custom_forms (company_id, title, description, access, status, fields, created_by)
select 'b86acc43-08df-4ef3-aae0-1653cb5a1fcd', 'Position Reassignment & Appointment Agreement — Yujung (Chris) Yong', 'For Yujung (Chris) Yong. Read the agreement, then sign and date it at the bottom. The CEO and Human Resources each sign their part after you submit.', 'internal', 'published', '[{"id":"fcyprv00","name":"title","type":"heading","label":"","style":{},"width":100,"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null,"config":{"text":"POSITION REASSIGNMENT & APPOINTMENT AGREEMENT","level":3,"bold":true,"alignment":"left"}},{"id":"fcyprv01","name":"agreement_text","type":"paragraph","label":"","style":{},"width":100,"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null,"config":{"html":"<p><strong>US In Home Services</strong> | Corporate Restructuring &amp; Governance Document</p><p>This Position Reassignment &amp; Appointment Agreement (\"Agreement\") is entered into and made effective as of <strong>October 14, 2026</strong> (\"Effective Date\"), by and between US In Home Services (\"Company\") and Yujung (Chris) Yong (\"Employee\").</p><p><strong>RECITALS</strong></p><p>WHEREAS, Employee has previously served in the capacity of Chief Operating Officer (COO) of the Company;</p><p>WHEREAS, the Board of Directors and Executive Leadership have conducted an operational review of corporate governance, labor compliance, and administrative controls within the operational division;</p><p><strong>WHEREAS</strong>, the Company and Employee have mutually evaluated operational requirements, corporate risk management profiles, and leadership alignment, determining that a transition in corporate status and operational responsibilities is necessary and in the best interests of both parties;</p><p>NOW, THEREFORE, in consideration of the mutual covenants contained herein and other good and valuable consideration, the receipt and sufficiency of which are hereby acknowledged, the parties agree as follows:</p><p><strong>SECTION 1: REASSIGNMENT &amp; SCOPE OF DUTIES</strong></p><p><strong>1.1 Relinquishment of Executive Officer Status</strong></p><p>As of the Effective Date, Employee hereby relinquishes, surrenders, and steps down from the executive officer position of Chief Operating Officer (COO). Employee ceases to hold any corporate officer status, statutory executive authority, or discretionary corporate signatory power associated with the COO title. All officer duties, fiduciary operational authorizations, and executive representations made on behalf of the Company are hereby revoked except as expressly designated in Section 1.2.</p><p><strong>1.2 Appointment to Director of Business Operations</strong></p><p>Effective October 14, 2026, Employee is appointed to the non-officer management role of <strong>Director of Business Operations (BizOps Director)</strong>.</p><p><strong>1.3 Scope of Primary Responsibilities</strong></p><p>In the capacity of BizOps Director, Employee''s core functional scope shall focus strictly on execution, analytical support, and administrative reporting under direct corporate supervision. Key responsibilities include:</p><ul><li><strong>Performance Analytics:</strong> Monitoring, compiling, and analyzing operational key performance indicators (KPIs) across business units.</li><li><strong>Process Support:</strong> Assisting in the maintenance, documentation, and continuous improvement of standardized internal operational workflows.</li><li><strong>Metrics Reporting:</strong> Preparing regular analytical dashboards and metrics reporting for review by Executive Leadership.</li><li><strong>Administrative Compliance:</strong> Supporting internal administrative procedures and tracking adherence to operational directives under explicit executive supervision.</li></ul><p><strong>SECTION 2: CORPORATE BACKGROUND &amp; REASSIGNMENT JUSTIFICATION</strong></p><p>This reassignment is grounded in the following findings and mutual acknowledgments regarding operational management during Employee''s tenure as Chief Operating Officer:</p><p><strong>2.1 Administrative &amp; Labor Compliance Oversights</strong></p><p>The Company identified significant administrative and regulatory oversights regarding operational record-keeping, personnel document management, and statutory labor compliance under the Fair Labor Standards Act (FLSA). These gaps created operational vulnerabilities that required immediate corporate remediation.</p><p><strong>2.2 Field Leadership &amp; Contracting Deficiencies</strong></p><p>Operational failures occurred in the management and execution of field leadership agreements. Specifically, verbal representations and informal promises regarding \"Branch Manager\" roles and titles were extended to field personnel without the required execution of formal, legally binding written employment contracts, offer letters, or statutory compliance documentation.</p><p><strong>2.3 Leadership Alignment &amp; Role Misunderstanding</strong></p><p>A structural misalignment was identified between the executive requirements of the COO role and Employee''s operational execution model. Employee adopted a passive, execution-only approach (\"following instructions\") rather than exercising proactive executive leadership, independent regulatory risk management, and rigorous corporate governance.</p><p><strong>2.4 Alignment of Skillset &amp; Risk Profile</strong></p><p>Both parties acknowledge and agree that Employee''s specific capabilities are optimal for structured performance analytics, process tracking, and operational support. Reassigning Employee to the BizOps Director role aligns Employee''s technical strengths with the Company''s strategic requirements while mitigating enterprise risk.</p><p><strong>SECTION 3: MANDATORY COMPLIANCE &amp; GOVERNANCE OBLIGATIONS</strong></p><p><strong>3.1 Strict Documentation Requirements</strong></p><p>Employee shall not make, communicate, or imply any binding offers, promises, or modifications regarding employment terms to any staff member or field personnel. <strong>ALL</strong> personnel actions—including but not limited to position grants, title modifications (specifically including Branch Manager designations), compensation adjustments, and field role definitions—must be formally documented in writing and receive explicit prior written authorization from the Chief Executive Officer (CEO) and Human Resources Department before implementation.</p><p><strong>3.2 Regulatory Compliance &amp; Record-Keeping</strong></p><p>Employee shall strictly adhere to all applicable federal, state, and local labor standards, including FLSA regulations, Department of Labor (DOL) rules, and internal corporate document management protocols. No informal or off-record operational agreements shall be permitted under any circumstances.</p><p><strong>SECTION 4: REPORTING LINE &amp; ACKNOWLEDGMENT</strong></p><p><strong>4.1 Executive Reporting Structure</strong></p><p>In the role of Director of Business Operations, Employee shall report directly to the Chief Executive Officer (Justin Lee) or such other executive designee as specified by the CEO.</p><p><strong>4.2 Entire Agreement &amp; Acknowledgment</strong></p><p>Employee acknowledges having carefully read this Agreement, fully understanding its terms, and accepting the reassignment and revised scope of duties set forth herein. This Agreement supersedes all prior agreements, oral representations, or understandings regarding Employee''s prior role as Chief Operating Officer.</p>","text":"","alignment":"left"}},{"id":"fcyprv02","name":"witness_rule","type":"divider","label":"","style":{},"width":100,"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null,"config":{"lineStyle":"solid","thickness":1,"color":"#9ca3af","spacing":8}},{"id":"fcyprv03","name":"witness_heading","type":"heading","label":"","style":{},"width":100,"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null,"config":{"text":"IN WITNESS WHEREOF","level":5,"bold":true,"alignment":"left"}},{"id":"fcyprv04","name":"witness_text","type":"paragraph","label":"","style":{},"width":100,"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null,"config":{"html":"<p>The parties hereto have executed this Position Reassignment &amp; Appointment Agreement as of the date first written above.</p>","text":"","alignment":"left"}},{"id":"fcyprv05","name":"company_heading","type":"heading","label":"","style":{},"width":100,"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null,"config":{"text":"COMPANY / EMPLOYER: US IN HOME SERVICES","level":5,"bold":true,"alignment":"left"},"fillBy":"company"},{"id":"fcyprv06","name":"ceo_signature","type":"signature","label":"Signature","style":{},"width":50,"hidden":false,"advanced":{},"readonly":false,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"config":{"canvasWidth":360,"canvasHeight":120,"penColor":"#0f172a","backgroundColor":"#ffffff","allowClear":true},"fillBy":"company"},{"id":"fcyprv07","name":"ceo_date","type":"datePicker","label":"Date","style":{},"width":50,"hidden":false,"advanced":{},"readonly":false,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"config":{"minDate":"","maxDate":"","disableWeekends":false,"dateFormat":"MM/DD/YYYY","timeZone":""},"fillBy":"company"},{"id":"fcyprv08","name":"ceo_name","type":"shortText","label":"Name","style":{},"width":50,"hidden":false,"advanced":{},"readonly":true,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"config":{},"defaultValue":"Justin Lee","fillBy":"company"},{"id":"fcyprv09","name":"ceo_title","type":"shortText","label":"Title","style":{},"width":50,"hidden":false,"advanced":{},"readonly":true,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"config":{},"defaultValue":"Chief Executive Officer (CEO)","fillBy":"company"},{"id":"fcyprv10","name":"employee_heading","type":"heading","label":"","style":{},"width":100,"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null,"config":{"text":"EMPLOYEE","level":5,"bold":true,"alignment":"left"}},{"id":"fcyprv11","name":"employee_signature","type":"signature","label":"Signature","style":{},"width":50,"hidden":false,"advanced":{},"readonly":false,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"config":{"canvasWidth":360,"canvasHeight":120,"penColor":"#0f172a","backgroundColor":"#ffffff","allowClear":true}},{"id":"fcyprv12","name":"employee_date","type":"datePicker","label":"Date","style":{},"width":50,"hidden":false,"advanced":{},"readonly":false,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"config":{"minDate":"","maxDate":"","disableWeekends":false,"dateFormat":"MM/DD/YYYY","timeZone":""}},{"id":"fcyprv13","name":"employee_name","type":"shortText","label":"Name","style":{},"width":50,"hidden":false,"advanced":{},"readonly":true,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"config":{},"defaultValue":"Yujung (Chris) Yong"},{"id":"fcyprv14","name":"employee_title","type":"shortText","label":"Title","style":{},"width":50,"hidden":false,"advanced":{},"readonly":true,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"config":{},"defaultValue":"Director of Business Operations"},{"id":"fcyprv15","name":"hr_heading","type":"heading","label":"","style":{},"width":100,"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null,"config":{"text":"HUMAN RESOURCES: US IN HOME SERVICES – HR DEPARTMENT","level":5,"bold":true,"alignment":"left"},"fillBy":"company"},{"id":"fcyprv16","name":"hr_signature","type":"signature","label":"Signature","style":{},"width":50,"hidden":false,"advanced":{},"readonly":false,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"config":{"canvasWidth":360,"canvasHeight":120,"penColor":"#0f172a","backgroundColor":"#ffffff","allowClear":true},"fillBy":"company"},{"id":"fcyprv17","name":"hr_date","type":"datePicker","label":"Date","style":{},"width":50,"hidden":false,"advanced":{},"readonly":false,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"config":{"minDate":"","maxDate":"","disableWeekends":false,"dateFormat":"MM/DD/YYYY","timeZone":""},"fillBy":"company"},{"id":"fcyprv18","name":"hr_name","type":"shortText","label":"Name","style":{},"width":50,"hidden":false,"advanced":{},"readonly":false,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"config":{},"fillBy":"company"},{"id":"fcyprv19","name":"hr_title","type":"shortText","label":"Title","style":{},"width":50,"hidden":false,"advanced":{},"readonly":true,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"config":{},"defaultValue":"Human Resources Manager","fillBy":"company"}]'::jsonb, '78d3504c-56f9-43a0-b7b1-091e3eba7d36'
where exists (select 1 from companies where id = 'b86acc43-08df-4ef3-aae0-1653cb5a1fcd')
